import{_ as t,o as a,c as r,a4 as e}from"./chunks/framework.DyX1TuK3.js";const g=JSON.parse('{"title":"駭客松沒方向時,怎麼把想法收斂成題目","description":"","frontmatter":{},"headers":[],"relativePath":"ideation.md","filePath":"ideation.md"}'),n={name:"ideation.md"};function s(l,o,i,h,p,d){return a(),r("div",null,[...o[0]||(o[0]=[e('<h1 id="駭客松沒方向時-怎麼把想法收斂成題目" tabindex="-1">駭客松沒方向時,怎麼把想法收斂成題目 <a class="header-anchor" href="#駭客松沒方向時-怎麼把想法收斂成題目" aria-label="Permalink to &quot;駭客松沒方向時,怎麼把想法收斂成題目&quot;">​</a></h1><blockquote><p>駭客松最難的往往不是寫程式,是第一天大家圍著白板「那我們要做什麼?」的卡頓。 這篇記錄這個專案怎麼從一堆零散想法收斂成一個能做完、做得出來的題目 —— 一套任何小團隊都能照用的方法。</p></blockquote><h2 id="前提-我們的起點" tabindex="-1">前提:我們的起點 <a class="header-anchor" href="#前提-我們的起點" aria-label="Permalink to &quot;前提:我們的起點&quot;">​</a></h2><p>四人團隊(1 PM、2 編輯、1 工程),一個共通背景:大家都在同一個內容產業工作。 沒有人一開始就知道要做什麼 —— 這很正常,也是重點:<strong>好題目不是想出來的,是篩出來的。</strong></p><hr><h2 id="_1-先發散-不要急著聚焦" tabindex="-1">① 先發散,不要急著聚焦 <a class="header-anchor" href="#_1-先發散-不要急著聚焦" aria-label="Permalink to &quot;① 先發散,不要急著聚焦&quot;">​</a></h2><p>第一步不是「找一個好點子」,是<strong>先攤開一批方向</strong>,不怕多、不怕重疊。 我們列了好幾個切角 —— 有的偏內容生產、有的偏情報蒐集、有的偏片單策展、 有的偏排程規劃。</p><p>這階段唯一的紀律:<strong>先求數量,不評好壞。</strong> 太早批評會殺掉還沒長大的點子。</p><hr><h2 id="_2-用「真實痛點」當篩子-不是挑最酷的" tabindex="-1">② 用「真實痛點」當篩子,不是挑最酷的 <a class="header-anchor" href="#_2-用「真實痛點」當篩子-不是挑最酷的" aria-label="Permalink to &quot;② 用「真實痛點」當篩子,不是挑最酷的&quot;">​</a></h2><p>收斂的關鍵不是「哪個最炫」,是<strong>哪個打中大家每天真的在痛的事</strong>。 我們把每個人的痛點攤出來,發現一個共同主題反覆出現:</p><blockquote><p>內容多到一個程度,「<strong>內容本身有沒有被好好理解、好好找得到</strong>」就成了瓶頸 —— 分類、檢索、整理,從不同角色的角度看都卡同一件事。</p></blockquote><p>→ 對齊到痛點後,「讓內容被理解 + 被找到」這條線立刻浮上來, 而幾個炫但沒人天天痛的方向(排程、跨通路改寫)自然沉下去。 <strong>三個人從不同角度都在痛同一件事,就是強訊號。</strong></p><hr><h2 id="_3-投票後「合併」-而不是「二選一」" tabindex="-1">③ 投票後「合併」,而不是「二選一」 <a class="header-anchor" href="#_3-投票後「合併」-而不是「二選一」" aria-label="Permalink to &quot;③ 投票後「合併」,而不是「二選一」&quot;">​</a></h2><p>投票後票數接近的不是只有一個。我們沒有硬二選一,而是看<strong>哪些可以疊成同一條主線</strong>: 把「自動理解內容」和「依需求找內容」併成一個彼此餵養的系統,而不是兩個各做一半。</p><blockquote><p>很多團隊卡在「到底選 A 還是 B」。其實常常答案是「A 為主、B 為輔」—— 把名次相近的選項看成可以疊加的層,而不是互斥的牆。</p></blockquote><hr><h2 id="_4-用「可行性」與「範圍」把題目切定" tabindex="-1">④ 用「可行性」與「範圍」把題目切定 <a class="header-anchor" href="#_4-用「可行性」與「範圍」把題目切定" aria-label="Permalink to &quot;④ 用「可行性」與「範圍」把題目切定&quot;">​</a></h2><p>收斂到後期,靠兩個現實問題定範圍:</p><ul><li><strong>這在駭客松時間內做得出來嗎?</strong> 技術門檻中等、prototype 跑得動的留; 要大量爬蟲 + 排程自動化那種工作量,直接標「之後有餘力再說」。</li><li><strong>最小要證明什麼?</strong> 與其功能堆滿,不如先把「核心體驗」做到能 demo。</li></ul><p>→ 限制不是敵人。<strong>「現在不做什麼」往往比「想做什麼」更快框出題目。</strong></p><hr><h2 id="_5-切出最小可驗證範圍-並且敢砍" tabindex="-1">⑤ 切出最小可驗證範圍,並且敢砍 <a class="header-anchor" href="#_5-切出最小可驗證範圍-並且敢砍" aria-label="Permalink to &quot;⑤ 切出最小可驗證範圍,並且敢砍&quot;">​</a></h2><p>最後把題目切成「核心先做 / 其餘先放」:</p><ul><li><strong>核心(實際做出來的)</strong>:自動標籤、語意搜尋、以及由此延伸的策展/獎項整理</li><li><strong>延伸(列了但砍掉)</strong>:即時情報蒐集那條 —— 工作量大、不是核心體驗, 最後<strong>刻意不做</strong>,把時間集中在能 demo 的主線上</li></ul><blockquote><p>列進提案、最後砍掉,不是失敗,是<strong>聚焦</strong>。駭客松最常見的死法是什麼都想做、 結果什麼都沒做完。能砍,題目才收得乾淨。</p></blockquote><p>並且當場分工 —— 誰負責資料、誰負責 UX、誰負責測品質、誰負責定義分類標準。 <strong>一個切得出 MVP、分得出工的題目,才算收斂完成。</strong></p><hr><h2 id="收斂的五步-濃縮成一句" tabindex="-1">收斂的五步,濃縮成一句 <a class="header-anchor" href="#收斂的五步-濃縮成一句" aria-label="Permalink to &quot;收斂的五步,濃縮成一句&quot;">​</a></h2><blockquote><p><strong>發散列多個 → 用真實痛點篩 → 名次相近就合併 → 用可行性框範圍 → 切出 MVP 並敢砍。</strong></p></blockquote><p>駭客松時間有限,花在「選對題目」的半天,比埋頭做錯方向的三天值得太多。 最好的題目,通常是「<strong>團隊真的在痛、技術做得出來、又剛好沒人做過</strong>」三者的交集。</p>',32)])])}const u=t(n,[["render",s]]);export{g as __pageData,u as default};
